python3 -c "
import csv
from collections import Counter, defaultdict

# Check what's landing in 'Other' L2 buckets and what's in Sports
for fname, src in [('data/amazon_product_categories.csv','amazon'), ('data/fb_product_categories.csv','facebook'), ('data/google_shopping_product_categories.csv','google')]:
    with open(fname, 'r', encoding='utf-8-sig') as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    # Sports L2 categories from source
    sport_l2 = Counter()
    health_l2 = Counter()
    clothing_l2 = Counter()
    for r in rows:
        path = r['category_path'].strip('\"')
        parts = [p.strip() for p in path.split('>')]
        top = parts[0].lower()
        if 'sport' in top or 'outdoor' in top:
            if len(parts) >= 2:
                sport_l2[parts[1].strip()] += 1
        elif 'health' in top or 'beauty' in top:
            if len(parts) >= 2:
                health_l2[parts[1].strip()] += 1
        elif 'cloth' in top or 'apparel' in top or 'fashion' in top:
            if len(parts) >= 2:
                clothing_l2[parts[1].strip()] += 1

    if sport_l2:
        print(f'{src} Sports L2:')
        for k, v in sport_l2.most_common(20):
            print(f'  {k}: {v}')
    if health_l2:
        print(f'{src} Health/Beauty L2:')
        for k, v in health_l2.most_common(20):
            print(f'  {k}: {v}')
    if clothing_l2:
        print(f'{src} Clothing L2:')
        for k, v in clothing_l2.most_common(20):
            print(f'  {k}: {v}')
    print()
" 2>&1

